classes.doc:
Интерфейс тайловой сущности.

 <p>Представляет тайловые сущности Minecraft — объекты внутри блоков (верстаки, сундуки, печи и т.д.).</p>

 <pre>{@code
    function main(c)
    {
        var te = c.getWorld().getTileEntity(371, 4, -100);

        if (te.getId() === "mappet:region")
        {
            var data = te.getData();

            // Replace on enter trigger of the tile entity to /toggledownfall
            data.getCompound("Region").setNBT("OnEnter", '{Blocks:[{Command:"/toggledownfall",Type:"command"}]}');
            te.setData(data);
        }
    }
 }</pre>

methods.doc:
Получить экземпляр тайловой сущности Minecraft. <b>ВНИМАНИЕ:</b> для прямого вызова методов нужны MCP mappings!

 <pre>{@code
 function main(c)
 {
     var itemInFirstSlot = c.getWorld().getTileEntity(-218, 101, 199).getMinecraftTileEntity().func_70301_a(0)

     c.send(itemInFirstSlot)
 }
 }</pre>

Получить идентификатор тайловой сущности.

 <pre>{@code
 function main(c)
 {
     var BlockTileEntity = c.getWorld().getTileEntity(-218, 101, 199)

     c.send(BlockTileEntity.getId())
 }
 }</pre>

Проверяет, недействительна ли эта тайловая сущность (удалена из мира или недоступна).

 <pre>{@code
 function main(c)
 {
     var BlockTileEntity = c.getWorld().getTileEntity(-218, 101, 199)

     c.send(BlockTileEntity.isInvalid())
 }
 }</pre>

Получить (копию) NBT-данных этой тайловой сущности.

 <pre>{@code
 function main(c)
 {
     var BlockTileEntity = c.getWorld().getTileEntity(-218, 101, 199)

     c.send(BlockTileEntity.getData())
 }
 }</pre>

Перезаписать NBT-данные этой тайловой сущности. <b>ВНИМАНИЕ</b>: используйте только если уверены — можно повредить сущность.

 <pre>{@code
 function main(c)
 {
     var BlockTileEntity = c.getWorld().getTileEntity(-218, 101, 199)
     var tag = mappet.createCompound('{CookTime:0,x:-218,BurnTime:0,y:101,z:199,Item:[],id:"minecraft:furnace",CookTimeTotal:0,Lock:""}')

     BlockTileEntity.setData(tag)
 }
 }</pre>

Получить пользовательский NBT-компаунд Forge для хранения любых данных.

 <p>Сеттер отсутствует — вы работаете с возвращённым компаундом напрямую. Любые изменения <b>сразу отразятся в данных тайловой сущности</b>.</p>

 <pre>{@code
 function main(c)
 {
     var BlockTileEntity = c.getWorld().getTileEntity(-218, 101, 199)

     c.send(BlockTileEntity.getTileData())
 }
 }</pre>

classes.doc:
Скриптовое состояние блока.

 <p>Представляет состояние блока, пригодное для сравнения или установки в мире. Можно получить состояние через {@link mchorse.mappet.api.scripts.user.IScriptFactory#createBlockState(String, int)}.</p>

 <pre>{@code
    var andesite = mappet.createBlockState("minecraft:stone", 5);

    function main(c)
    {
        if (c.getWorld().getBlock(214, 3, 511).isSame(andesite))
        {
            c.getSubject().send("Block at (214, 3, 511) is indeed andesite!");
        }
    }
 }</pre>

methods.doc:
Получить идентификатор блока, например <code>minecraft:stone</code>.

 <pre>{@code
    var block = c.getWorld().getBlock(214, 3, 511);

    c.getSubject().send("Block at (214, 3, 511) is " + block.getBlockId());
 }
 }</pre>

Получить значение meta этого состояния (всегда будет между 0 и 15).

 <pre>{@code
    var andesite = mappet.createBlockState("minecraft:stone", 5);

    // This will print "Andesite's meta is 5"
    c.getSubject().send("Andesite's meta is " + andesite.getMeta());
 }
 }</pre>

Проверяет, совпадает ли это состояние блока с заданным состоянием.

 <pre>{@code
    var andesite = mappet.createBlockState("minecraft:stone", 5);

    if (c.getWorld().getBlock(214, 3, 511).isSame(andesite))
    {
        c.getSubject().send("Block at (214, 3, 511) is indeed andesite!");
    }
 }
 }</pre>

Проверяет, совпадает ли тип блока с заданным, игнорируя meta (необязательно то же значение meta).

 <pre>{@code
    var andesite = mappet.createBlockState("minecraft:stone", 5);
    var stone = mappet.createBlockState("minecraft:stone", 0);

    // This will print true
    c.getSubject().send(stone.isSameBlock(andesite));
 }
 }</pre>

Преобразует этот вектор в строку массива

 <pre>{@code
 function main(c)
 {
     var subject = c.getSubject();
     var subjectPosition = subject.getPosition();
     c.send("The player is at " + subjectPosition.toArrayString() + "!");
     // The player is at [x, y, z]!
 }
 }</pre>

classes.doc:
Скриптовый бокс — область в пространстве

 <pre>{@code
 function main(c)
 {
     var subject = c.getSubject();
     var subjectPosition = subject.getPosition();
     var box = mappet.box(-10, 4, -10, 10, 6, 10);
     if (box.contains(subjectPosition)){
         c.send("the player in in the box")
     }
 }
 }</pre>

methods.doc:
Сдвигает бокс на указанные смещения

 <pre>{@code
 function main(c)
 {
     var box = mappet.box(-10, 4, -10, 10, 6, 10);
     box.offset(10, 0, 10);
     c.send(box.toString()); // ScriptBox(0.0, 4.0, 0.0, 20.0, 6.0, 20.0)
 }
 }</pre>

Проверяет, находится ли точка с заданными координатами внутри бокса

 <pre>{@code
 function main(c)
 {
     var box = mappet.box(-10, 4, -10, 10, 6, 10);
     if (box.contains(0, 4, 0)){
         c.send("this point is inside the box")
     }
     if (box.contains(0, 7, 0)){
         c.send("this point is outside the box")
     }
 }
 }</pre>

Проверяет, лежат ли указанные координаты внутри этого бокса

 <pre>{@code
 function main(c)
 {
     var subject = c.getSubject();
     var subjectPosition = subject.getPosition();
     var box = mappet.box(-10, 4, -10, 10, 6, 10);
     if (box.contains(subjectPosition)){
         c.send("the player in in the box")
     }
 }
 }</pre>

Возвращает список позиций блоков в боксе, соответствующих заданному состоянию блока в указанном мире.

 <pre>{@code
 function main(c)
 {
     var world = c.getWorld();
     var state = mappet.createBlockState("minecraft:stone");
     var box = mappet.box(-10, 4, -10, 10, 6, 10);
     var blockPositions = box.getBlocksPositions(world, state);

     var blockPositionsString = "[";
     blockPositions.forEach(function(position) {
         blockPositionsString += position.toArrayString() + ", ";
     });
     blockPositionsString = blockPositionsString.substring(0, blockPositionsString.length - 2);
     blockPositionsString += "]";
     print(blockPositions);
 }
 }</pre>

classes.doc:
Интерфейс сущности игрока.

 <p>Представляет сущность игрока.</p>

 <pre>{@code
    function main(c)
    {
        if (c.getSubject().isPlayer())
        {
            // Do something with the player...
        }
    }
 }</pre>

methods.doc:
Выполняет клиентский скрипт на стороне игрока. Используется функция <code>main</code>.

 <pre>{@code
    var player = c.getSubject();

    if (player.executeClientScript("client_script"))
    {
        // скрипт отправлен на выполнение
    }
 }</pre>

Выполняет клиентский скрипт на стороне игрока и вызывает указанную функцию. Если функция пустая, используется <code>main</code>.

 <pre>{@code
    var player = c.getSubject();

    if (player.executeClientScript("client_script", "onTick"))
    {
        // скрипт отправлен на выполнение
    }
 }</pre>

Выполняет клиентский скрипт на стороне игрока, вызывает указанную функцию и передаёт ей аргументы. Если функция пустая, используется <code>main</code>. Аргументы попадают в функцию скрипта по порядку; значения Boolean/числа/строки сохраняют тип, остальные передаются как строки.

 <pre>{@code
    var player = c.getSubject();

    if (player.executeClientScript("client_script", "onTick", 42, "hello", true))
    {
        // скрипт отправлен на выполнение
    }
 }</pre>

Выполняет переданную функцию прямо на клиенте игрока, без отдельного файла скрипта. Функция описывается в серверном скрипте и отправляется на клиент, где вызывается. Внутри доступны объекты <code>c</code> (событие), <code>mappet</code> и <code>context</code> (клиентский DataContext).

 <pre>{@code
    var player = c.getSubject();

    player.executeClientScript(function()
    {
        var client = c.getSubject();
        client.send("Это сообщение показал код, отправленный с сервера");
    });
 }</pre>

Выполняет переданную функцию на клиенте игрока и передаёт ей аргументы. Аргументы попадают в функцию по порядку; значения Boolean/числа/строки сохраняют тип, остальные передаются как строки.

 <pre>{@code
    var player = c.getSubject();

    player.executeClientScript(function(message, count)
    {
        for (var i = 0; i < count; i++)
        {
            var client = c.getSubject();
            client.send(message);
        }
    }, "Привет!", 3);
 }</pre>

Применяет сохранённый шейдер к миру игрока и, при необходимости, к интерфейсу Mappet и HUD. ID — имя файла из вкладки «Шейдеры» без расширения. <code>ui</code> включает интерфейс Mappet, <code>hud</code> — весь HUD. Новый шейдер заменяет предыдущий в каждом выбранном слое. Если оба флага не нужны, можно вызвать коротко: <code>applyShader("wave")</code>. Вызов не меняет файл и не включает шейдер другим игрокам. При включённом Iris/Oculus экранный слой накладывается поверх готового цвета shader pack перед отрисовкой руки; внутренние буферы shader pack не изменяются.

 <pre>{@code
function main(c)
{
    var s = c.getSubject();

    // Мир, интерфейс Mappet и HUD
    s.applyShader("wave", true, true);
}
}</pre>

Применяет сохранённый шейдер ко всему HUD у этого игрока: ванильным индикаторам и HUD Mappet. Мир и открытый интерфейс Mappet не меняются. Этот проход работает вместе с Iris/Oculus, потому что обрабатывает отдельный прозрачный слой HUD после shader pack. В одном режиме одновременно работает один шейдер.

 <pre>{@code
function main(c)
{
    var s = c.getSubject();

    s.applyHUDShader("hud_glow");
}
}</pre>

Снимает шейдер с HUD у этого игрока.

 <pre>{@code
function main(c)
{
    var s = c.getSubject();

    s.removeShader();
    s.removeUIShader();
    s.removeHUDShader();
}
}</pre>

Получает режим игры игрока.

 <pre>{@code
    // Assuming that c.getSubject() is a player
    var player = c.getSubject();
    var gamemode = player.getGameMode();

    if (gamemode === 0)
    {
        player.send("You're in survival mode!");
    }
 }</pre>

Устанавливает режим игры игрока.

 <pre>{@code
    // Assuming that c.getSubject() is a player
    var player = c.getSubject();
    var gamemode = c.getSubject().getGameMode();

    // When player exits the mining region, set their game mode back to adventure
    if (gamemode === 0 && !player.getStates().has("region.mining_factory"))
    {
        player.setGameMode(2);
    }
 }
 }</pre>

Включает или выключает постоянный режим ползания игрока, реализованный через ванильную позу плавания. При <code>true</code> игрок ползает по земле и не встаёт сам при тике или смене позы. Режим остаётся включённым, пока скрипт не вызовет <code>setLay(false)</code>.

 <pre>{@code
function main(c)
{
    var player = c.getSubject();

    player.setLay(true);  // включить постоянное ползание
    // player.setLay(false); // вернуть обычную позу
}
}</pre>

Получает инвентарь игрока.

 <pre>{@code
    // Assuming that c.getSubject() is a player
    var inventory = c.getSubject().getInventory();
    var item = mappet.createItem("minecraft:diamond_sword");

    // This will change the first slot in the hotbar to a diamond sword
    inventory.setStack(0, item);
 }</pre>

Получает инвентарь эндер-сундука игрока.

 <pre>{@code
    // Assuming that c.getSubject() is a player
    var inventory = c.getSubject().getEnderChest();
    var item = mappet.createItem("minecraft:diamond_sword");

    // This will change the first slot in player's ender chest to a diamond sword
    inventory.setStack(0, item);
 }</pre>

Выполняет команду от имени игрока.

 <pre>{@code
    function main(c)
    {
        c.getSubject().executeCommand("/kill");
    }
 }</pre>

Устанавливает точку возрождения игрока.

 <pre>{@code
   c.getSubject().setSpawnPoint(0, 0, 0);
 }</pre>

Получает точку возрождения игрока.

 <pre>{@code
   var spawnPoint = c.getSubject().getSpawnPoint();
   c.send("Spawn point: " + spawnPoint.x + ", " + spawnPoint.y + ", " + spawnPoint.z);
 }</pre>

Проверяет, летает ли игрок.

 <pre>{@code
    function main(c) {
        c.send("Is the player flying? " + c.getSubject().isFlying());
    }
 }</pre>

Возвращает базовую (ванильную) скорость ходьбы игрока. Стандарт в Minecraft — <code>0.1</code>. Для управления через множитель используй <code>getWalkSpeedMultiplier()</code>.

 <pre>{@code
function main(c)
{
    c.send("Скорость игрока: " + c.getSubject().getWalkSpeed());
}
}</pre>

Включает разрешение игроку летать в любом режиме игры.

 <pre>{@code
 c.getSubject().setFlyingEnabled(true);
 }</pre>

Возвращает скорость полёта игрока.

 <pre>{@code
    function main(c)
    {
        c.send("The flight speed of the player is: " + c.getSubject().getFlySpeed());
    }
 }</pre>

Устанавливает базовую (ванильную) скорость ходьбы игрока. Стандарт — <code>0.1</code>. Для управления через множитель используй <code>setWalkSpeedMultiplier()</code>.

 <pre>{@code
function main(c)
{
    c.getSubject().setWalkSpeed(0.2);
}
}</pre>

Устанавливает скорость полёта игрока.

 <pre>{@code
    function main(c)
    {
        c.getSubject().setFlySpeed(0.5);
    }
 }</pre>

Сбрасывает скорость полёта игрока.

 <pre>{@code
    function main(c)
    {
        c.getSubject().resetFlySpeed();
    }
 }</pre>

Сбрасывает скорость ходьбы к стандартному ванильному значению <code>0.1</code>. Метод всегда устанавливает базовое значение заново.

 <pre>{@code
function main(c)
{
    c.getSubject().resetWalkSpeed();
}
}</pre>

Возвращает время отката для предмета по индексу в инвентаре игрока.

 <pre>{@code
    function main(c)
    {
        var player = c.getSubject();
        var item = mappet.createItem("minecraft:diamond_sword");
        var cooldown = player.getCooldown(item);

        c.send(The held item cooldown " + ((1 - cooldown) * 100) + " percent expired.");
    }
 }</pre>

Устанавливает откат для указанного предмета.

 <pre>{@code
    function main(c)
    {
        var player = c.getSubject();
        var item = mappet.createItem("minecraft:diamond_sword");

        player.setCooldown(item, 100);
    }
 }</pre>

Сбрасывает откат для предмета по индексу в инвентаре игрока.

 <pre>{@code
    function main(c)
    {
        var player = c.getSubject();
        var item = mappet.createItem("minecraft:diamond_sword");

        player.resetCooldown(item);
    }
 }</pre>

Возвращает индекс слота в хотбаре для основного предмета. Полезно, например, для методов отката главной руки.

 <pre>{@code
    function main(c)
    {
        var player = c.getSubject();

        player.setCooldown(player.getHotbarIndex(), 100); //tip: 40 is the offhand slot
    }
 }</pre>

Отправляет сообщение игроку.

 <pre>{@code
    // Assuming that c.getSubject() is a player
    c.send("I love all my players equally.");
    c.getSubject().send("...but between you and me, you're my favorite player ;)");
 }</pre>

Отправляет сообщение с текстовым компонентом (как команда <code>/tellraw</code>).

 <pre>{@code
    var message = mappet.createCompound();

    message.setString("text", "This message displays an item...");
    message.setString("color", "gold");
    message.setNBT("hoverEvent",'{action:"show_item",value:"{id:\\"minecraft:diamond_hoe\\",Count:1b}"}');

    c.getSubject().sendRaw(message);
 }</pre>

Отправить длительности отображения title и subtitle (в тиках, <code>20</code> тиков = <code>1</code> секунда).
Эти значения нужно отправлять до отправки title или subtitle.

<p><b>ВНИМАНИЕ</b>: эти значения длительностей останутся прежними до выхода игрока, поэтому, возможно, стоит
менять их каждый раз перед отправкой title и subtitle.</p>

<p>Значения по умолчанию: fadeIn = <code>10</code> тиков, idle = <code>70</code> тиков,
fadeOut = <code>20</code> тиков.</p>

<pre>{@code
    var player = c.getSubject();

    player.sendTitleDurations(5, 10, 5);
    player.sendTitle("Quick!");
    player.sendSubtitle("Get into cover!");
 }
 }</pre>

Отправить этому игроку заголовок, который будет отображаться в центре экрана.

<pre>{@code
    c.getSubject().sendTitle("Hello, world!");
 }
 }</pre>

Отправить этому игроку подзаголовок, который будет отображаться в центре экрана. Чтобы подзаголовок появился, заголовок нужно отправить через {@link #sendTitle(String)}.

<pre>{@code
    c.getSubject().sendTitle("Hello,");
    c.getSubject().sendSubtitle("world!");
 }
 }</pre>

Установить уровень опыта и количество очков для этого уровня.

<pre>{@code
    // For more information of how levels work (i.e. how many points per
    // level to level up) see this table:
    // https://minecraft.fandom.com/wiki/Experience#Leveling_up

    // Set player's XP level to 17 and half of the bar (level 17 has
    // 42 points in total to level up)
    c.getSubject().setXp(17, 21);
 }
 }</pre>

Добавить очки опыта этому игроку. Если добавить больше очков, чем может вместить текущий уровень игрока, это приведёт к повышению уровня один или несколько раз.

<pre>{@code
    // For more information of how levels work (i.e. how many points per
    // level to level up) see this table:
    // https://minecraft.fandom.com/wiki/Experience#Leveling_up

    // Add 1000 experience points
    c.getSubject().addXp(1000);
 }
 }</pre>

Получить текущий уровень опыта игрока.

<pre>{@code
    // For more information of how levels work (i.e. how many points per
    // level to level up) see this table:
    // https://minecraft.fandom.com/wiki/Experience#Leveling_up

    var s = c.getSubject();

    if (s.getXpLevel() < 50)
    {
        var section = "§";

        // Teleport the player out of the area
        s.setPosition(10, 4, -15);
        s.send("Come back when you're level" + section + "7 50" + section + "r!");
    }
 }
 }</pre>

Проиграть звуковое событие только этому игроку — с заданной громкостью и тоном.

 <pre>{@code
    var player = c.getSubject();
    var pos = player.getPosition();

    player.playSound("minecraft:entity.pig.ambient", pos.x, pos.y, pos.z, 1.0, 0.8);
 }</pre>

Остановить все звуки, воспроизводящиеся для этого игрока.

 <pre>{@code
    c.getWorld().stopAllSounds();
 }</pre>

Проиграть статичный звук на указанном канале только для этого игрока.

 <p>В отличие от {@link #playSound(String, double, double, double, float, float)},
 при телепортации игрока такой звук не прерывается.</p>

 <pre>{@code
    var player = c.getSubject();

    player.playStaticSound("minecraft:block.portal.ambient", "voice", 1.0, 0.8);

    c.scheduleScript(20, function (c)
    {
        c.getSubject().setPosition(-15, 4, 561);
    });
 }</pre>

Вернуть квесты сущности (если есть — квесты есть только у игроков).

 <pre>{@code
    // Assuming that c.getSubject() is a player
    var quests = c.getSubject().getQuests();

    if (!quests.has("important_quest"))
    {
        c.getSubject().send("I think you should complete the main quest chain before attempting side quests...");
    }
 }</pre>

Открывает сохранённый файл интерфейса из вкладки <b>UI</b>. ID — путь без расширения, например <code>terminal/login</code>. При открытии по строковому ID используются скрипт и функция из настроек файла интерфейса.

<pre>{@code
function main(c)
{
    c.getSubject().openUI("terminal/login");
}
}</pre>

Закрывает активный интерфейс Mappet, открытый через <code>openUI</code>. Обычно используется после <code>closeUI()</code>, чтобы закрыть любой тип меню одной цепочкой. Если открыт обычный экран, его закроет первый вызов; если открыт UI Mappet, его закроет второй.

 <pre>{@code
var s = c.getSubject();

// Закрыть обычное меню или UI Mappet
s.closeUI().closeMappetUI();
}</pre>

Возвращает фракции NPC в виде строк.

 <pre>{@code
 for each (var faction in c.getSubject().getFactions()){
    c.send(faction)
 }
 }</pre>

Вернуть все HUD‑сцены (включая глобальные), которые сейчас показываются этому игроку.

 <pre>{@code
   var player = c.getSubject();
   var huds = player.getDisplayedHUDs();
   print(huds);
 }</pre>

Вернуть все глобальные HUD‑сцены, которые сохранены у игрока и сейчас отображаются ему и другим игрокам.

 <pre>{@code
   var player = c.getSubject();
   var huds = player.getGlobalDisplayedHUDs();
   print(huds);
 }</pre>

Запускает сцену Aperture для этого игрока.

 <pre>{@code
 c.getSubject().playScene("scene_name");
 }</pre>

Проигрывает сцены Aperture для этого игрока.

 <pre>{@code
 c.getSubject().stopScene();
 }</pre>

Записывает текст в буфер обмена выбранного игрока. Изменение видно только на его клиенте.

<pre>{@code
var player = c.getSubject();
player.setClipboard("Скопировано из скрипта Mappet");
}</pre>

Запросить буфер обмена выбранного игрока и вернуть последнее полученное от его клиента значение. Чтение идёт по сети, поэтому первый вызов обычно возвращает пустую строку — он только отправляет запрос. Чтобы получить актуальный результат, вызовите этот метод, а затем прочитайте его в скрипте, запущенном через несколько тиков.

<pre>{@code
var player = c.getSubject();
player.getClipboard(); // отправляет запрос клиенту
c.scheduleScript("clipboard", "read", 2);

function read(c)
{
    c.send(c.getSubject().getClipboard());
}
}</pre>

Получить доступ к одному элементу стандартного HUD Minecraft. При вводе названия в кавычках редактор предложит доступные элементы: <code>Crosshair</code>, <code>Hotbar</code>, <code>Health</code>, <code>Hunger</code>, <code>Experience</code>, <code>StatusEffects</code>, <code>MountHealth</code>, <code>Vignette</code>, <code>Spyglass</code> и <code>ItemTooltip</code>. <pre>{@code
function main(c)
{
    var crosshair = c.subject.getAllHud("Crosshair");
    crosshair.render(false);
}
}</pre>

Вернуть объект клиентских настроек выбранного игрока. Все изменения применяются только на его клиенте — не меняют настройки других игроков и не требуют перезахода.

<pre>{@code
var settings = c.getSubject().getSettings();
settings.setFov(90);
settings.setHudHidden(true);
}</pre>

Получить управление тряской камеры у выбранного игрока. Эффект виден только ему и не влияет на камеру других участников.
<pre>{@code
function main(c)
{
    var shake = c.subject.getCameraShake();
    shake.start(40, 1.5, 8);
}
}</pre>

Открыть HTTP/HTTPS-ссылку в браузере выбранного игрока. Откроется только у него; небезопасные схемы, например <code>file:</code> или <code>javascript:</code>, блокируются.

<pre>{@code
var player = c.getSubject();
player.openWeb("https://example.com");
}</pre>

Переключить уже открытый HUD между режимом fullbright и освещением мира. Возвращает <code>false</code>, если HUD с данным ID не открыт у игрока.

<pre>{@code
function main(c)
{
    var s = c.getSubject();
    s.setupHUD("npc_preview");
    s.setHUDWorldLighting("npc_preview", true);
}
}</pre>

classes.doc:
Интерфейс NPC-сущности Mappet.

 <pre>{@code
    function main(c)
    {
        if (c.getSubject().isNPC())
        {
            // Do something with the NPC...
        }
    }
 }</pre>

methods.doc:
Получить ID этого NPC.

 <pre>{@code
    var pos = c.getSubject().getPosition();
    var npc = c.getWorld().spawnNpc("test", pos.x, pos.y + 2, pos.z);

    // This will output "true" as long as you have an NPC configured
    // in Mappet's NPC dashboard panel
    c.send(npc.getNpcId() === "test");
 }</pre>

Получить состояние NPC.

 <pre>{@code
    c.send(c.getSubject().getNpcState());
 }</pre>

Установить состояние NPC.

 <pre>{@code
    c.getSubject().setNpcState("default");
 }</pre>

Разрешить NPC подбирать предметы.

 <pre>{@code
    c.getSubject().canPickUpLoot(true);
 }</pre>

Заставить NPC следовать за целью.

 <pre>{@code
    c.getSubject().follow("@r");
 }</pre>

Разрешить или запретить управление NPC.

 <pre>{@code
 c.getSubject().setCanBeSteered(true);
 }</pre>

Проверить, можно ли управлять NPC.

 <pre>{@code
 c.getSubject().canBeSteered();
 }</pre>

Установить смещение управления для NPC.

 <pre>{@code
 c.getSubject().setSteeringOffset(index, x, y, z);
 }</pre>

Добавить смещение управления NPC.

 <pre>{@code
 c.getSubject().addSteeringOffset(x, y, z);
 }</pre>

Получить все смещения управления NPC.

 <pre>{@code
 c.getSubject().getSteeringOffsets().forEach((offset) -> {
     c.send(offset.x + ", " + offset.y + ", " + offset.z);
 });
 }</pre>

Установить скорость NPC.

 <pre>{@code
 c.getSubject().setNpcSpeed(speed);
 }</pre>

Возвращает скорость NPC.

 <pre>{@code
 c.getSubject().getNpcSpeed();
 }</pre>

Задаёт силу прыжка NPC.

 <pre>{@code
 c.getSubject().setJumpPower(jumpHeight);
 }</pre>

Возвращает силу прыжка NPC.

 <pre>{@code
 c.getSubject().getjumpPower();
 }</pre>

Задаёт, неуязвим ли NPC.

 <pre>{@code
 c.getSubject().setInvincible(true);
 }</pre>

Возвращает true, если NPC неуязвим.

 <pre>{@code
 c.getSubject().isInvincible();
 }</pre>

Задаёт, может ли NPC плавать.

 <pre>{@code
 c.getSubject().setCanSwim(true);
 }</pre>

Возвращает true, если NPC может плавать.

 <pre>{@code
 c.getSubject().canSwim();
 }</pre>

Задаёт, неподвижен ли NPC.

 <pre>{@code
 c.getSubject().setImmovable(true);
 }</pre>

Возвращает true, если NPC неподвижен.

 <pre>{@code
 c.getSubject().isImmovable();
 }</pre>

Задаёт размер тени NPC.

 <pre>{@code
 c.getSubject().setShadowSize(0.8);
 }</pre>

Возвращает размер тени NPC.

 <pre>{@code
 var size = c.getSubject().getShadowSize();
 }</pre>

Задаёт количество опыта (XP) NPC.

 <pre>{@code
 c.getSubject().setXpValue(10);
 }</pre>

Возвращает XP у NPC.

 <pre>{@code
 var xp = c.getSubject().getXpValue();
 }</pre>

Возвращает path distance у NPC. Также это радиус обзора для опции "look at player".

 <pre>{@code
 var distance = c.getSubject().getPathDistance();
 }</pre>

Устанавливает path distance у NPC. Также задаёт радиус обзора для опции "look at player".

 <pre>{@code
 c.getSubject().setPathDistance(10);
 }</pre>

Устанавливает attack range у NPC.

 <pre>{@code
 c.getSubject().setAttackRange(5);
 }</pre>

Возвращает attack range у NPC.

 <pre>{@code
 var range = c.getSubject().getAttackRange();
 }</pre>

Устанавливает статус killable у NPC. Если false, NPC можно убить только командой. Вне зависимости от значения, killable позволяет наносить NPC урон до 0 здоровья.

 <pre>{@code
 c.getSubject().setKillable(true);
 }</pre>

Возвращает, является ли NPC killable. Если false, NPC можно убить только командой. Вне зависимости от значения, killable позволяет снизить здоровье NPC до 0.

 <pre>{@code
 var isKillable = c.getSubject().isKillable();
 }</pre>

Возвращает, может ли NPC получать урон от огня (burnable).

 <pre>{@code
 var canGetBurned = c.getSubject().canGetBurned();
 }</pre>

Включает или выключает возможность NPC сгорать.

 <pre>{@code
 c.getSubject().canGetBurned(true);
 }</pre>

Возвращает, может ли NPC получать урон от падения.

 <pre>{@code
 var canFallDamage = c.getSubject().canFallDamage();
 }</pre>

Включает или выключает урон от падения для NPC.

 <pre>{@code
 c.getSubject().canFallDamage(true);
 }</pre>

Возвращает силу урона NPC (в очках).

 <pre>{@code
 var damage = c.getSubject().getDamage();
 }</pre>

Задаёт силу урона NPC.

 <pre>{@code
 c.getSubject().setDamage(10);
 }</pre>

Возвращает задержку урона NPC.

 <pre>{@code
 var delay = c.getSubject().getDamageDelay();
 }</pre>

Задаёт задержку урона NPC.

 <pre>{@code
 c.getSubject().setDamageDelay(5);
 }</pre>

Возвращает, блуждает ли NPC.

 <pre>{@code
 var doesWander = c.getSubject().doesWander();
 }</pre>

Устанавливает, будет ли NPC блуждать.

 <pre>{@code
 c.getSubject().setWander(true);
 }</pre>

Возвращает, оглядывается ли NPC в простое (осматривается по сторонам).

 <pre>{@code
 var doesLookAround = c.getSubject().doesLookAround();
 }</pre>

Устанавливает, будет ли NPC оглядываться в простое.

 <pre>{@code
 c.getSubject().setLookAround(true);
 }</pre>

Возвращает, смотрит ли NPC на игрока.

 <pre>{@code
 var doesLookAtPlayer = c.getSubject().doesLookAtPlayer();
 }</pre>

Устанавливает, будет ли NPC смотреть на игрока.

 <pre>{@code
 c.getSubject().setLookAtPlayer(true);
 }</pre>

Удаляет точку патруля NPC по индексу.

 <pre>{@code
 c.getSubject().removePatrolPoint(0);
 }</pre>

Удаляет точку патруля NPC по координатам.

 <pre>{@code
 var npc = c.getSubject();
 var pos = npc.getPosition();
 npc.removePatrolPoint(pos.x, pos.y, pos.z);
 }</pre>

Удаляет все точки патрулирования NPC.

 <pre>{@code
 c.getSubject().clearPatrolPoints();
 }</pre>

Добавляет новую точку в маршрут патрулирования NPC. Точки идут в том порядке, в котором их добавили. Для каждой новой точки автоматически создаётся пустой триггер, поэтому списки точек и триггеров всегда совпадают.

<pre>{@code
var npc = c.getSubject();

// Собрать маршрут из трёх точек
npc.clearPatrolPoints();
npc.addPatrol(10, 64, -5);
npc.addPatrol(15, 64, -5);
npc.addPatrol(15, 64, 0);
}</pre>

Изменяет координаты существующей точки патруля. Индекс начинается с <code>0</code>. Если индекс выходит за границы маршрута, метод ничего не делает.

<pre>{@code
var npc = c.getSubject();

// Перенести первую точку маршрута
npc.setPatrol(0, 20, 64, 10);
}</pre>

Возвращает возраст сущности.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     c.getSubject().send("Item's age: " + entityItem.getAge());
 }
 }</pre>

Задаёт возраст сущности.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     entityItem.setAge(5000);
     c.getSubject().send("Item's age: " + entityItem.getAge());
 }
 }</pre>

Возвращает задержку подбора сущности.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     c.getSubject().send("You can pick up this item in " + entityItem.getPickupDelay() + " ticks.");
 }
 }</pre>

Задаёт задержку подбора сущности.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     entityItem.setPickupDelay(100); // 5 seconds
     c.getSubject().send("You can pick up this item in " + entityItem.getPickupDelay() + " ticks.");
 }
 }</pre>

Возвращает продолжительность жизни сущности (максимальный возраст).

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     c.getSubject().send("Item disappear in " + (entityItem.getLifespan() - entityItem.getAge()) + " ticks.");
 }
 }</pre>

Задаёт срок жизни сущности (максимальный возраст).

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     entityItem.setLifespan(1200); // 60 seconds
     c.getSubject().send("Item disappear in " + (entityItem.getLifespan() - entityItem.getAge()) + " ticks.");
 }
 }</pre>

Возвращает ник владельца сущности (кто может подобрать предмет). Пустая строка — если подобрать может любой.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     c.getSubject().send(entityItem.getOwner());
 }
 }</pre>

Задает ник владельца сущности — кто может подобрать этот предмет. Оставьте пустую строку, если подобрать может любой.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     entityItem.setOwner(c.getSubject().getName());
 }
 }</pre>

Получить ник бросившего сущность (кто бросил этот предмет). Возвращает пустую строку, если предмет создан через код.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     c.getSubject().send(entityItem.getThrower());
 }
 }</pre>

Установить ник бросившего сущность — кто бросил этот предмет.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond_hoe");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);
     entityItem.setThrower(c.getSubject().getName());
 }
 }</pre>

Получить itemStack у этой сущности.

 <pre>{@code
 function main(c)
 {
     var pos = c.getSubject().getPosition();
     var entities = c.getWorld().getEntities(pos.x, pos.y + 1, pos.z, 3);

     for (var i in entities)
     {
         var entity = entities[i];

         if (entity.isItem())
         {
             c.player.send(entity.getItem().getItem().getId());
         }
     }
 }
 }</pre>

Изменить itemStack у этой сущности (пример: превратить предметы в радиусе 3 блоков в золотые самородки).

 <pre>{@code
 // Midas :D
 // Turns any item in radius of 3 blocks into golden nuggets.
 function main(c)
 {
     var pos = c.getSubject().getPosition();
     var entities = c.getWorld().getEntities(pos.x, pos.y + 1, pos.z, 3);

     for (var i in entities)
     {
         var entity = entities[i];

         if (entity.isItem())
         {
             entity.setItem(mappet.createItem("minecraft:golden_nugget"))
         }
     }
 }
 }</pre>

Делает предмет неподбираемым.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);

     entityItem.setNoDespawn();
     entityItem.setInfinitePickupDelay();
 }
 }</pre>

Сущность не будет деспауниться.

 <pre>{@code
 function main(c)
 {
     var item = mappet.createItem("minecraft:diamond");
     var pos = c.getSubject().getPosition();

     var entityItem = c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z);

     entityItem.setNoDespawn();
     entityItem.setInfinitePickupDelay();
 }
 }</pre>

Проверяет, можно ли подобрать этот предмет.

 <pre>{@code
 // Item magnet :D
 function main(c)
 {
     var player = c.getSubject();
     var pos = player.getPosition();
     var entities = c.getWorld().getEntities(pos.x, pos.y + 1, pos.z, 10);

     for (var i in entities)
     {
         var entity = entities[i];

         if (entity.isItem() && entity.canPickup())
         {
             player.giveItem(entity.getItem());
             entity.remove(); // despawn
         }
     }
 }
 }</pre>

classes.doc:
Интерфейс сущности.

 <p>Этот интерфейс представляет любую сущность — игрока, NPC или другую сущность. <b>ВАЖНО</b>: любой метод, отмеченный как {@link IScriptEntity}, может также вернуть {@link IScriptPlayer} для реального игрока или {@link IScriptNpc} для NPC Mappet!</p>

 <pre>{@code
     function main(c)
     {
         if (c.getSubject().isPlayer())
         {
             // Do something with the player...
         }
         if (c.getSubject().isNPC())
         {
             // Do something with the NPC...
         }
         else
         {
             // Do something with the entity...
         }
     }
 }
 }</pre>

methods.doc:
Возвращает управление интеграцией Simple Voice Chat для этой сущности — работает, если мод установлен. Для игрока можно отключить его микрофон на сервере через <code>setMute</code> или локально заглушить конкретного говорящего у этого игрока через <code>setPlayerMuted</code>. Если Simple Voice Chat не установлен, методы безопасно ничего не делают.

 <pre>{@code
 function main(c)
 {
     var voice = c.getSubject().getSVC();
     voice.setMute(true); // Сервер больше не передаёт голос subject
     voice.setPlayerMuted(c.getPlayer("Alex"), true); // Subject локально не слышит Alex
 }
 }</pre>

Получает нативный экземпляр сущности Minecraft. <b>ОСТОРОЖНО:</b> для прямых вызовов методов нужны отображения MCP!

 <pre>{@code
 function main(c)
 {
     //c.getSubject().getMinecraftEntity().abilities.disableDamage = true
     c.getSubject().getMinecraftEntity().field_71075_bZ.field_75102_a = true // or false
 }
 }</pre>

Получает мир, в котором находится сущность.

 <pre>{@code
    var s = c.getSubject();
    var world = s.getWorld();

    world.setRaining(true);
 }</pre>

Получает позицию сущности.

 <pre>{@code
    var pos = c.getSubject().getPosition();

    c.send(c.getSubject().getName() + "'s position is (" + pos.x + ", " + pos.y + ", " + pos.z + ")");
 }</pre>

Устанавливает позицию сущности (телепорт).

 <pre>{@code
    c.getSubject().setPosition(800, 8, -135);
 }</pre>

Возвращает измерение, в котором находится сущность.

 <pre>{@code
   var dimension = c.getSubject().getDimension();
   switch (dimension)
   {
       case 0: c.send("Overworld"); break;
       case 1: c.send("The End"); break;
       case -1: c.send("The Nether"); break;
       default: c.send("Unknown dimension"); break;
   }
 }</pre>

Возвращает вектор скорости (motion) сущности.

 <pre>{@code
    var motion = c.getSubject().getMotion();

    c.send(c.getSubject().getName() + "'s motion is (" + motion.x + ", " + motion.y + ", " + motion.z + ")");
 }</pre>

Устанавливает вектор скорости (motion) сущности.

 <pre>{@code
    var motion = c.getSubject().getMotion();

    if (motion.y < 0)
    {
        // Reverse the falling motion into a jumping up motion
