 }</pre>

Сбрасывает повороты AI сущности

 <pre>{@code
     c.getSubject().clearRotationsAI();
 }</pre>

Выполняет команду на сущности с указанной периодичностью (в тиках).

 <pre>{@code
    c.getSubject().executeRepeatingCommand("/tp @s ~ ~2 ~", 20);
}</pre>

Удаляет повторяющуюся команду у сущности.

 <pre>{@code
    c.getSubject().removeRepeatingCommand("/tp @s ~ ~2 ~");
 }</pre>

Удаляет все повторяющиеся команды у сущности.

 <pre>{@code
    c.getSubject().clearAllRepeatingCommands();
 }</pre>

Плавно поворачивает сущность. Параметры такие же, как у <code>moveTo</code>: ключ интерполяции, длительность в тиках и временное отключение AI. Поворот по yaw идёт по кратчайшей дуге.

 <pre>{@code
    // Повернуть NPC направо за секунду с мягкой интерполяцией
    npc.rotateTo("SINE_INOUT", 20, 0, 90, 90, true);
 }</pre>

classes.doc:
Представляет мир, переданный в событии.

 <pre>{@code
    function main(c)
    {
        var world = c.getWorld();

        // Do something with world...
    }
 }</pre>

methods.doc:
Возвращает экземпляр мира Minecraft. <b>ВНИМАНИЕ:</b> для прямых вызовов его методов нужны сопоставления MCP.

 <pre>{@code
 function main(c)
 {
     var seaLevel = c.getWorld().getMinecraftWorld().field_181546_a //Sea level

     c.send(seaLevel)
 }
 }</pre>

Устанавливает игровое правило в указанное значение.

 <pre>{@code
   c.getWorld().setGameRule("keepInventory", true); //btw you can NOT write 1 instead of true
   c.getWorld().setGameRule("randomTickSpeed", 100);
 }</pre>

Получает значение игрового правила.

 <pre>{@code
   var keepInventory = c.getWorld().getGameRule("keepInventory");
   var randomTickSpeed = c.getWorld().getGameRule("randomTickSpeed");

   c.send("Keep inventory: " + keepInventory);
   c.send("Random tick speed: " + randomTickSpeed);
 }</pre>

Устанавливает блок в координатах XYZ. Используйте {@link IScriptFactory#createBlockState(String, int)} для создания состояния блока.

 <pre>{@code
    var coarse_dirt = mappet.createBlockState("minecraft:dirt", 1);

    c.getWorld().setBlock(coarse_dirt, 214, 3, 509);
 }</pre>

Удаляет блок по указанным координатам XYZ.

 <pre>{@code
   c.getWorld().removeBlock(214, 3, 509);
 }</pre>

Возвращает состояние блока по указанным координатам XYZ.

 <pre>{@code
    var block = c.getWorld().getBlock(mappet.vector3(214, 3, 509));

    c.send("Block at (214, 3, 509) is " + block.getBlockId());
 }</pre>

Проверяет, есть ли tile entity по указанным координатам XYZ.

 <pre>{@code
 function main(c)
 {
     var hasTileEntity = c.getWorld().hasTileEntity(0, 80, 0)

     c.send(hasTileEntity)
 }
 }</pre>

Заменяет все блоки в указанной области на заданное состояние блока и записывает данные tile entity.

 <pre>{@code
 c.getWorld().replaceBlocks(
    mappet.createBlockState("minecraft:dirt", 0),
    mappet.createBlockState("blockbuster:model", 0),
    mappet.createCompound('{Morph:{Settings:{Hands:1b},Name:"blockbuster.fred"},id:"minecraft:blockbuster_model_tile_entity"}'),
    mappet.vector3(171, 61, 279),
    mappet.vector3(176, 64, 276)
 );
 }</pre>

Получает tile entity по указанным координатам XYZ.

 <pre>{@code
    var tile = c.getWorld().getTileEntity(214, 3, 509);

    if (tile)
    {
        c.send("Tile entity at (214, 3, 509) is " + tile.getId());
    }
    else
    {
        c.send("There is no tile entity at (214, 3, 509)");
    }
 }</pre>

Проверяет, есть ли инвентарь (tile entity) по указанным координатам XYZ.

 <pre>{@code
    var world = c.getWorld();

    if (world.hasInventory(214, 4, 512))
    {
        var inventory = world.getInventory(214, 4, 512);

        inventory.setStack(0, mappet.createItem("minecraft:diamond_hoe"));
        c.send("There is a surprise for you in chest at (214, 4, 512) :)");
    }
    else
    {
        c.send("There is no chest at (214, 4, 512)...");
    }
 }</pre>

Получает инвентарь (tile entity) по указанным координатам XYZ.

 <pre>{@code
    var world = c.getWorld();
    var inventory = world.getInventory(214, 4, 512);

    if (world.hasInventory(214, 4, 512))
    {
        var inventory = world.getInventory(214, 4, 512);

        inventory.clear();
    }
 }</pre>

Проверяет, идёт ли дождь в мире.

 <pre>{@code
    var world = c.getWorld();
    var pos = c.getSubject().getPosition();

    // If it's raining in the world, then drop a diamond
    // If not, then drop a dirt block
    if (world.isRaining())
    {
        world.dropItemStack(mappet.createItem("minecraft:diamond"), pos.x, pos.y + 3, pos.z);
    }
    else
    {
        world.dropItemStack(mappet.createItem("minecraft:dirt"), pos.x, pos.y + 3, pos.z);
    }
 }</pre>

Устанавливает, идёт ли дождь.

 <pre>{@code
    c.getWorld().setRaining(true);
    c.send("The ritual dance got successfully completed!");
 }
 }</pre>

Возвращает текущее игровое время (то, которое задаёт команда <code>/time set</code>).

 <pre>{@code
    if (c.getWorld().getTime() % 24000 > 12000)
    {
        c.getSubject().send("Good night!");
    }
    else
    {
        c.getSubject().send("Good day!");
    }
 }</pre>

Устанавливает текущее игровое время.

 <pre>{@code
    c.getWorld().setTime(14000);
    c.send("Another ritual dance got successfully completed!");
 }
 }</pre>

Возвращает общее время жизни мира в тиках.

 <pre>{@code
    if (c.getWorld().getTotalTime() > 20 * 600)
    {
        c.send("You had only 10 minutes to complete the map...");
        c.send("Initiating SELF-DESTRUCT mode!");

        // TODO: implement self-destruction
    }
 }
 }</pre>

Возвращает ID измерения мира.

 <pre>{@code
    if (c.getWorld().getDimensionId() == 0)
    {
        c.getSubject().send("You're in overworld!");
    }
    else
    {
        c.getSubject().send("*shrugs*");
    }
 }
 }</pre>

Создаёт ванильные частицы только для указанного игрока.

 <pre>{@code
    var explode = mappet.getParticleType("explode");
    var pos = c.getSubject().getPosition();

    c.getWorld().spawnParticles(c.getSubject(), explode, false, pos.x, pos.y, pos.z, 10, 0.1, 0.1, 0.1, 0.1);
 }</pre>

Создаёт сущность в указанной позиции и позволяет передать дополнительные данные.

 <pre>{@code
    var pos = c.getSubject().getPosition();

    // Spawn a baby zombie
    c.getWorld().spawnEntity("minecraft:zombie", pos.x, pos.y + 3, pos.z, mappet.createCompound("{IsBaby:1b}"));
 }</pre>

Создаёт NPC в заданной позиции с указанным состоянием и поворотом.

 <pre>{@code
    var pos = c.getSubject().getPosition();

    c.getWorld().spawnNpc("herobrine", "dabbing", pos.x, pos.y, pos.z, 0, 0, 0);
 }</pre>

Получает сущности в сфере вокруг указанных координат с заданным радиусом в этом мире. Поиск ограничен радиусом в <b>50 блоков</b> в любую сторону. Если у заданной сферы радиус превышает 100 блоков, метод вернёт пустой список.

 <pre>{@code
    var pos = c.getSubject().getPosition();
    var entities = c.getWorld().getEntities(pos.x, pos.y + 1, pos.z, 3);

    for (var i in entities)
    {
        var entity = entities[i];

        if (!entity.isSame(c.getSubject()))
        {
            entity.damage(2.0);
        }
    }
 }</pre>

Воспроизвести звуковое событие в мире с указанной громкостью и тоном.

 <pre>{@code
    var pos = c.getSubject().getPosition();

    c.getWorld().playSound("minecraft:entity.pig.ambient", pos.x, pos.y, pos.z, 1.0, 0.8);
 }</pre>

Остановить все воспроизводимые звуки для всех игроков.

 <pre>{@code
    c.getWorld().stopAllSounds();
 }</pre>

Выбросить стек предметов в указанной позиции XYZ этого мира с заданной скоростью.

 <pre>{@code
    var item = mappet.createItem("minecraft:diamond_hoe");
    var pos = c.getSubject().getPosition();

    c.getWorld().dropItemStack(item, pos.x, pos.y + 3, pos.z, 0, 1, 0);
 }</pre>

Создаёт взрыв в мире в указанных координатах и радиусе; укажите сущность‑инициатора.

 <pre>{@code
 function main(c)
 {
     var s = c.getSubject();
     var pos = s.getPosition();

     c.getWorld().explode(s, pos.x, pos.y, pos.z, 10, false, false)
 }
 }</pre>

Проверяет, активна ли кнопка, плита или рычаг.

 <pre>{@code
     c.getWorld().isActive(0, 4, 0);
 }</pre>

Проверяет, есть ли в указанных координатах блок с заданным meta-значением.

 <pre>{@code
     function main(c)
     {
         var pos = c.getSubject().getPosition()

         if (c.getWorld().testForBlock(Math.floor(pos.x), Math.floor(pos.y), Math.floor(pos.z), "minecraft:light_weighted_pressure_plate", 1))
         {
             c.send("Prussure Plate is pressed.")
         }
     }
 }</pre>

Заполняет 3D-область блоком.

 <pre>{@code
     var coarse_dirt = mappet.createBlockState("minecraft:dirt", 1);

     c.getWorld().fill(coarse_dirt, -3, 100, -3, 3, 100, 3);
 }</pre>

Призывает падающий блок с указанным id блока и meta-значением.

 <pre>{@code
     c.getWorld().summonFallingBlock(0, 100, 0, "minecraft:dirt", 1);
 }</pre>

Преобразует блок в падающий по заданным координатам.

 <pre>{@code
     c.getWorld().setFallingBlock(0, 100, 0);
 }</pre>

Устанавливает тайловую сущность в указанных координатах.

 <pre>{@code
 c.getWorld().setTileEntity(
     530, 152, 546,
     mappet.createBlockState("blockbuster:model", 0),
     mappet.createCompound('{Morph:{Settings:{Hands:1b},Name:"blockbuster.fred"},id:"minecraft:blockbuster_model_tile_entity"}')
 );
   }</pre>

Заполняет область тайловыми сущностями.

 <pre>{@code
 c.getWorld().fillTileEntities(530, 152, 546, mappet.createBlockState("blockbuster:model", 0), mappet.createCompound('{Morph:{Settings:{Hands:1b},Name:"blockbuster.fred"},id:"minecraft:blockbuster_model_tile_entity"}'));
   }</pre>

Копирует блоки в другие координаты.

 <pre>{@code
 function main(c)
 {
     c.getWorld().clone(0, 80, 0, 0, 83, 0)
 }
 }</pre>

Возвращает стек блока на указанной позиции вместе с данными tile entity.

 <pre>{@code
    var x= 0, y = 100, z = 0;
    var world = c.getWorld();
    var blockItemStack = world.getBlockStackWithTile(x, y, z);
    world.setBlock(mappet.createBlockState("minecraft:air", 0), x, y, z)
    world.dropItemStack(blockItemStack, x+0.5, y+0.5, z+0.5);
 }</pre>

Создаёт новый пустой объект Schematic.

 <pre>{@code
 function main(c)
 {
     var schematic = c.world.createSchematic();
     schematic.loadFromWorld(0, 4, 0, 4, 8, 4).saveToFile("mySchematic").place(0, 4, 4).place(0, 4, 8);
 }
 }</pre>

Показывает world-морф игроку в заданной точке с поворотом. Морф находится в этом мире на некотором удалении в блоках.

<pre>{@code
 function main(c)
 {
     var s = c.getSubject();
     var morph = mappet.createMorph('{Name:"item"}');
     var pos = s.getPosition();

     var yaw = s.getYaw()
     var pitch = s.getPitch()

     c.getWorld().displayMorph(morph, 100, pos.x, pos.y + s.getHeight() + 0.5, pos.z, yaw, pitch, 90, s);
 }
 }</pre>

Выстреливает сущностью-снарядом оружия.

 <pre>{@code
     var projectile = c.getWorld().shootBBGunProjectile(c.getSubject(), 547, 160, 497, 0, -90, '{Gun:{TickCommand:"particle heart ~ ~1 ~ 0.2 0.2 0.2 1",StoredAmmo:0,Ticking:1,Damage:1.0f,Projectile:{Meta:0b,Block:"minecraft:stone",Name:"block"},Gravity:0.0f}}')
     c.scheduleScript(20, function (c){
         projectile.executeCommand("summon tnt ~ ~ ~")
         projectile.remove()
     });
 }</pre>

classes.doc:
Интерфейс сервера, переданного в событии.

 <pre>{@code
    function main(c)
    {
        var server = c.getServer();

        // Do something with server...
    }
 }</pre>

methods.doc:
Получить мир по ID измерения.

 <pre>{@code
    var overworld = c.getServer().getWorld(0);

    // Do something with the world...
 }</pre>

Получить все сущности, соответствующие указанному селектору целей.

 <pre>{@code
    var cows = c.getServer().getEntities("@e[type=minecraft:cow]");

    // Despawn all cows
    for (var i in cows)
    {
        cows[i].remove();
    }
 }</pre>

Найти сущность по её UUID.

 <pre>{@code
    var uuid = "29a91933-86f2-4683-8a87-218084d8c927";
    var entity = c.getServer().getEntity(uuid);

    print(entity.getUniqueId() === uuid); // true
 }</pre>

Получить всех игроков на сервере.

 <pre>{@code
    var players = c.getServer().getAllPlayers();

    for (var i in players)
    {
        // Surprise :)
        players[i].setMotion(0, 0.5, 0);
    }
 }</pre>

Найти игрока по имени пользователя.

 <pre>{@code
    var player = c.getServer().getPlayer("Notch");

    if (player)
    {
        // I'm about to pull a prank on Notch... >:)
        //
        // Or give a nice present... :)
    }
 }</pre>

Проверить, онлайн ли игрок.

 <pre>{@code
    if (!c.getServer().isOnline("McHorse"))
    {
        c.send("McHorse is not online. :(")
    }
 }</pre>

Получить глобальные состояния сервера.

 <pre>{@code
    var states = c.getServer().getStates();

    if (states.getNumber("total_money_earned") > 1000000000)
    {
        // Give all players an achievement or something...
    }
 }</pre>

Проверить, существует ли сущность с заданным UUID.

 <pre>{@code
    if (c.getServer().entityExists("29a91933-86f2-4683-8a87-218084d8c927"))
    {
        // Do something...
    }
 }</pre>

Выполнить скрипт по имени; по умолчанию будет вызвана функция "main".

 <pre>{@code
    c.getServer().executeScript("example_script.js");
 }</pre>

Выполнить скрипт с указанной функцией.

 <pre>{@code
    c.getServer().executeScript("example_script.js", "custom_function");
 }</pre>

Выполнить скрипт — указать файл, функцию и аргументы.

 <pre>{@code
 c.getServer().executeScript("example_script.js", "func_with_context", c, 1, 2, 3);
 c.getServer().executeScript("example_script.js", "func_without_context", 1, 2, 3);

 // example_script.js
 function func_with_context(c, arg1, arg2, arg3)
 {
     c.send("arg1: " + arg1 + ", arg2: " + arg2 + ", arg3: " + arg3);
 }

 function func_without_context(arg1, arg2, arg3)
 {
     print("arg1: " + arg1 + ", arg2: " + arg2 + ", arg3: " + arg3);
 }
 }</pre>

classes.doc:
Интерфейс, представляющий результат трассировки луча.

 <pre>{@code
    function main(c)
    {
        var result = c.getSubject().rayTrace(32);

        if (result.isBlock())
        {
            // Ray hit a block, so we'll change the block to diamond block
            var pos = result.getBlock();

            c.getWorld().setBlock(mappet.createBlockState("minecraft:diamond_block", 0), pos.x, pos.y, pos.z);
        }
        else if (result.isEntity())
        {
            // Ray hit an entity, so we'll throw it in the air
            result.getEntity().setMotion(0, 1, 0);
        }
        else // if (result.isMissed())
        {
            c.send("Good luck next time!");
        }
    }
 }</pre>

Фабрика Scripting API, позволяющая создавать и инициализировать разные объекты.

 <p>В скрипте к ней можно обратиться через глобальную переменную <code>mappet</code>. Вот пример кода:</p>

 <pre>{@code
    function main(c) {
        // Create a diamond hoe using Mappet's factory
        var item = mappet.createItem("minecraft:diamond_hoe");

        c.getSubject().setMainItem(item);
    }
 }</pre>

methods.doc:
Возвращает состояние блока, пригодное для установки и сравнения блоков в {@link IScriptWorld}.

 <pre>{@code
    var fence = mappet.createBlockState("minecraft:fence", 0);

    // minecraft:fence 0
    c.send(fence.getBlockId() + " " + fence.getMeta());
 }</pre>

Создаёт состояние блока с метаданными по умолчанию.

 <pre>{@code
 var fence = mappet.createBlockState("minecraft:fence");

 // minecraft:fence 0
 c.send(fence.getBlockId() + " " + fence.getMeta());
 }</pre>

Создаёт пустой NBT-компаунд.

 <pre>{@code
    var tag = mappet.createCompound();

    tag.setString("id", "minecraft:diamond_hoe");
    tag.setByte("Count", 1);

    var item = mappet.createItemNBT(tag);

    // {id:"minecraft:diamond_hoe",Count:1b,Damage:0s}
    c.send(item.serialize());
 }</pre>

Парсит NBT-компаунд из строки. При некорректном NBT вернёт пустой компаунд.

 <pre>{@code
    var tag = mappet.createCompound("{id:\"minecraft:diamond_hoe\",Count:1b}");
    var item = mappet.createItemNBT(tag);

    // {id:"minecraft:diamond_hoe",Count:1b,Damage:0s}
    c.send(item.serialize());
 }</pre>

Преобразует JS-объект в NBT-компаунд.

 <p><b>ВНИМАНИЕ</b>: при конвертации JS-объекта в NBT учтите ограничения формата NBT:</p>

 <ul>
     <li>NBT поддерживает несколько форматов хранения чисел (byte, short, int, long, float,
     double), поэтому конвертер сможет преобразовывать числа только в теги NBT типа
     integer или double, в зависимости от того, как вы получили число: <code>42</code>
     — целое, а <code>42.0</code> — double.</li>
     <li>Списки NBT поддерживают хранение только <b>одного типа</b> элементов одновременно, поэтому
     если вы передадите JS-массив вроде <code>[0, 1, 2, "test", {a:1,b:2}, 4, [0, 0, 0], 5.5]</code>,
     то будет учтён <b>только тип первого элемента</b>, и получившийся NBT-список будет выглядеть как <code>[0.0d, 1.0d, 2.0d, 4.0d, 5.5d]</code>.
     <b>В случае с числами</b>, если сначала идут целые, а где‑то в середине списка появится double, то целые <b>будут преобразованы
     в double</b>!</li>
 </ul>

 <pre>{@code
    var tag = mappet.createCompoundFromJS({id:"minecraft:diamond_hoe",Count:1});
    var item = mappet.createItemNBT(tag);

    // {id:"minecraft:diamond_hoe",Count:1b,Damage:0s}
    c.send(item.serialize());
 }</pre>

Создаёт пустой NBT-список.

 <pre>{@code
    var list = mappet.createList();

    list.addInt(1);
    list.addInt(2);
    list.addInt(3);
    list.addInt(4);
    list.addInt(5);
    list.addInt(6);

    // [1,2,3,4,5,6]
    c.send(list.stringify());
 }</pre>

Парсит NBT-список из строки. При неверной строке вернёт пустой список.

 <pre>{@code
    var list = mappet.createList("[1, 2, 3, 4, 5, 6]");

    // [1,2,3,4,5,6]
    c.send(list.stringify());
 }</pre>

Преобразует JS-объект в NBT-компаунд.

 <p><b>Тщательно прочитайте описание</b> {@link #createCompoundFromJS(Object)}
 для получения информации об ограничениях при конвертации JS-объектов в NBT!</p>

 <pre>{@code
    var list = mappet.createListFromJS([1, 2, 3, 4, 5, 6]);

    // [1,2,3,4,5,6]
    c.send(list.stringify());
 }</pre>

Создаёт стек предметов из строкового NBT.

 <pre>{@code
    var item = mappet.createItemNBT("{id:\"minecraft:enchanted_book\",Count:1b,tag:{StoredEnchantments:[{lvl:4s,id:4s}]},Damage:0s}");

    // It will output "minecraft:enchanted_book"
    c.send(item.getItem().getId());
 }</pre>

Создаёт стек предметов из NBT-компаунда.

 <pre>{@code
    var tag = mappet.createCompound("{id:\"minecraft:diamond_hoe\",Count:1b}");
    var item = mappet.createItemNBT(tag);

    // {id:"minecraft:diamond_hoe",Count:1b,Damage:0s}
    c.send(item.serialize());
 }</pre>

