Создаёт UI, который можно показать игроку через {@link IScriptPlayer#openUI(IMappetUIBuilder)}.

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI().background();
        var label = ui.label("Hello, world!").background(0x88000000);

        label.rxy(0.5, 0.5).wh(80, 20).anchor(0.5).labelAnchor(0.5);

        c.getSubject().openUI(ui);
    }
 }</pre>

Создаёт UI со скриптовым обработчиком. Показать игроку можно через {@link IScriptPlayer#openUI(IMappetUIBuilder)}.



 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var label = ui.label("Hello, world!").background(0x88000000);
        var button = ui.button("Push me!").id("button");

        label.rxy(0.5, 0.5).wh(80, 20).anchor(0.5).labelAnchor(0.5);
        label.rx(0.5).ry(0.5, 25).wh(80, 20).anchor(0.5);

        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();

        if (uiContext.getLast() === "button")
        {
            // Button was pressed
        }
    }
 }</pre>

Создаёт UI с обработчиком на скрипте. Откройте UI игроку через {@link IScriptPlayer#openUI(IMappetUIBuilder)}.

<p>Аргументы "script" и "function" позволяют указать функцию в скрипте, которая будет обрабатывать ввод из UI.</p>

<p>В обработчике есть доступ к UI-контексту субъекта ({@link IMappetUIContext}) — в нём все нужные методы для работы с вводом.</p>

<pre>{@code
    // ui.js
    function main(c)
    {
        var ui = mappet.createUI("handler", "main").background();
        var label = ui.label("Hello, world!").background(0x88000000);
        var button = ui.button("Push me!").id("button");

        label.rxy(0.5, 0.5).wh(80, 20).anchor(0.5).labelAnchor(0.5);
        label.rx(0.5).ry(0.5, 25).wh(80, 20).anchor(0.5);

        c.getSubject().openUI(ui);
    }

    // handler.js
    function main(c)
    {
        var uiContext = c.getSubject().getUIContext();

        if (uiContext.getLast() === "button")
        {
            // Button was pressed
        }
    }
 }</pre>

Загружает сохранённый UI-файл и создаёт UI из него. Достаточно указать ID, чтобы использовать обратный вызов и функцию из файла. Три аргумента позволяют явно задать обработчик.

<pre>{@code
function main(c) {
    let s = c.subject;
    let ui = mappet.createUIFromFile("test", "test.js", "handler");

    s.openUI(ui)
}

function handler(c) {
    let s = c.subject;
    let uic = s.UIContext;
    let last = uic.getLast();

    if(last == "button_1"){
        c.send(1);
    }
}
 }</pre>

Получить глобальный произвольный объект.

