Создать 2D-вектор.

 <pre>{@code
    var a = mappet.vector2(1, 0);
    var b = mappet.vector2(-1, 1);

    a.normalize();
    b.normalize();

    c.send("Dot product of a and b is: " + a.dot(b));
 }</pre>

Создать копию 2D-вектора.

 <pre>{@code
    var a = mappet.vector2(25, 17);
    var b = mappet.vector2(a);

    b.x += 40;
    b.y -= 5;

    var d = mappet.vector2(b);

    d.sub(a);

    c.send("Distance between a and b is: " + d.length());
 }</pre>

Создать 3D-вектор.

 <pre>{@code
    var look = c.getSubject().getLook();
    var a = mappet.vector3(look.x, look.y, look.z);
    var b = mappet.vector3(0, 0, 1);

    a.normalize();
    b.normalize();

    c.send("Dot product of entity's look vector and positive Z is: " + a.dot(b));
 }</pre>

Создаёт копию 3D-вектора.

 <pre>{@code
    var pos = c.getSubject().getPosition();
    var a = mappet.vector3(pos.x, pos.y, pos.z);
    var b = mappet.vector3(10, 4, 50);

    var d = mappet.vector3(b);

    d.sub(a);

    c.send("Distance between you and point (10, 4, 50) is: " + d.length());
 }</pre>

Создаёт единичную матрицу 3x3.

 <pre>{@code
    var v = mappet.vector3(0, 0, 1);
    var rotation = mappet.matrix3();

    rotation.rotY(Math.PI / 2);
    rotation.transform(v);

    c.send("Final point is: " + v);
 }</pre>

Создаёт единичную матрицу 4x4.

 <pre>{@code
    var v = mappet.vector4(0, 0, 1, 1);
    var rotation = mappet.matrix4();

    rotation.rotY(Math.PI / 2);

    var translation = mappet.matrix4();

    translation.setTranslation(mappet.vector3(0, 4, 0));
    rotation.mul(translation);
    rotation.transform(v);

    c.send("Final point is: " + v.x + ", " + v.y + ", " + v.z);
 }</pre>

Создаёт ограничивающий объём.

 <pre>{@code
 function main(c)
 {
     var subject = c.getSubject();
     var subjectPosition = subject.getPosition();
     var box = mappet.box(-10, 4, -10, 10, 6, 10);
     if (box.contains(subjectPosition)){
         c.send("the player in in the box")
     }
 }
 }</pre>

Проверяет, лежит ли точка внутри ограничивающего объёма, заданного двумя противоположными угловыми точками. Работает с векторами 2D, 3D и 4D.

 <pre>{@code
   var pos = c.getSubject().getPosition();
   var point = mappet.vector3(pos.x, pos.y, pos.z);
   var bound1 = mappet.vector3(0, 0, 0);
   var bound2 = mappet.vector3(10, 10, 10);
   var isInside = mappet.isPointInBounds(point, bound1, bound2);
   c.send("Is the point inside the bounding volume? " + isInside);
 }</pre>

Форматирует строки с подстановками.

 <pre>{@code
 // Example:
 var name = "Steve";
 var age = 18;
 var message = mappet.format("Hello %s, you are %d years old!", name, age);
 c.send(message);

 // You can also use the positional arguments:
 var s = c.getSubject();
 var pos = s.getPosition();
 var message = mappet.format("Hello %1$s, you are in x:%2$.2f, y:%3$.2f, z:%4$.2f!", s.getName(), pos.x, pos.y, pos.z);
 s.send(message);
 }</pre>

Отменяет событие триггера. 

<p>В зависимости от типа это остановит действие по умолчанию (например, при отмене триггера чата сообщение не будет отправлено).</p>

<pre>{@code
    // Assuming this script was attached to global trigger "On block placed,"
    // this script will cancel placing of the block by a player
    function main(c)
    {
        if (c.getValue("block") === "minecraft:stone")
        {
            c.cancel();
        }
    }
 }</pre>

Возвращает уникальный ID запланированной задачи — его можно передать в `cancelScheduleScript(id)` для отмены. Запланирует выполнение текущего скрипта (той же функции) через указанное число тиков. 

<p>Смотрите {@link #scheduleScript(String, String, int)} для дополнительной информации.</p>

<pre>{@code
    function main(c)
    {
        var states = c.getServer().getStates();
        var counter = states.getNumber("counter");

        if (counter < 10)
        {
            c.send(counter + " Mississippi...");
            states.add("counter", 1);

            c.scheduleScript(20);
        }
        else
        {
            states.reset("counter");
            c.send("Here I go!");
        }
    }
 }</pre>

Возвращает уникальный ID запланированной задачи — его можно передать в `cancelScheduleScript(id)` для отмены. Запланирует выполнение указанной функции того же скрипта через заданное число тиков. 

<p>Смотрите {@link #scheduleScript(String, String, int)} для дополнительной информации.</p>

<pre>{@code
    function main(c)
    {
        // Schedule script execution of function other
        // within same script a second later
        c.scheduleScript("other", 20);
    }

    function other(c)
    {
        c.send("A second ago, function \"main\" told me to say \"hi\" to you... :)")
    }
 }</pre>

Возвращает идентификатор запланированной задачи. Передай его в <code>cancelScheduleScript(id)</code>, чтобы отменить задачу. Запускает указанный скрипт и функцию через заданное число тиков.

<p>Запланированная функция получит те же данные, что и текущая: цель, объект, мир, сервер и значения.</p>

<p>Значения, добавленные через {@link #setValue(String, Object)}, будут доступны и при запуске задачи.</p>

<pre>{@code
    // Script "a"
    function main(c)
    {
        // As ProTip states, you can pass some value using
        // setValue() and getValue() event's functions
        c.setValue("message", "Hello!");

        // Schedule script "b" execution a second later
        c.scheduleScript("b", "main", 20);
    }

    // Script "b"
    function main(c)
    {
        c.send("A second ago, script \"a\" told me deliver this message: " + c.getValue("message"));
    }
 }</pre>

Возвращает уникальный ID запланированной задачи — его можно передать в `cancelScheduleScript(id)` для отмены. Запланирует выполнение JavaScript-функции: после таймера указанная функция будет вызвана с текущим контекстом в качестве единственного аргумента.

<pre>{@code
    function main(c)
    {
        c.scheduleScript(60, function (context)
        {
            context.send("This was called three seconds later!");
        });
    }
 }
 }</pre>

Выполнить команду.

<pre>{@code
    c.executeCommand("/kick Creeper501");
 }
 }</pre>

Отправить сообщение всем игрокам в общий чат.

<pre>{@code
    c.send("Hi :)");
 }
 }</pre>

Отменяет одну задачу, запланированную через `scheduleScript`. Возвращает `true`, если задача найдена и удалена из очереди, иначе `false`.

<pre>{@code
function main(c)
{
    var taskId = c.scheduleScript(100, function (context)
    {
        context.send("Это сообщение уже не будет отправлено");
    });

    c.scheduleScript(20, function (context)
    {
        context.cancelScheduleScript(taskId);
        context.send("Задача отменена");
    });
}
}</pre>

