Интерфейс логгера Mappet.

 <p>Используйте {@link IScriptFactory#getLogger()} для получения экземпляра логгера Mappet.</p>

 <pre>{@code
    var logger = mappet.getLogger();

    logger.info("Hello world!");
 }</pre>

UI-контекст — объект с данными интерфейса, пока игрок открыл пользовательский GUI, созданный с помощью {@link IMappetUIBuilder}.

 <p>Обычно он доступен в обработчике после отправки UI с помощью {@link IScriptPlayer#openUI(IMappetUIBuilder)}.</p>

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var button = ui.button("Push me").id("button");

        // Place a button in the middle of the screen
        button.rxy(0.5, 0.5).wh(80, 20).anchor(0.5);
        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();

        // Do something with UI context...
    }
 }</pre>

methods.doc:
Возвращает NBT-компаунд с данными UI.

 <p>Данные формируют компоненты UI с заданным ID. Они заполняются только когда элементы действительно меняют свои значения — до этого компаунд пуст.</p>

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var name = ui.textbox().id("name");
        var lastname = ui.textbox().id("lastname");

        // Place two text fields in the middle of the screen
        name.rxy(0.5, 0.5).wh(140, 20).anchor(0.5);
        lastname.rx(0.5).ry(0.5, 25).wh(140, 20).anchor(0.5);

        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();

        // If the user will input first in the name text box, the data
        // will be just {name:"John"}. If the user will input first
        // the lastname, then the data will be {lastname:"Appleseed"}.
        // Once both fields will be edited, you'll get:
        // {name:"John",lastname:"Appleseed"}
        c.send(uiContext.getData().stringify());
    }
 }</pre>

Проверяет, был ли интерфейс только что закрыт.

 <p>Вернёт <code>true</code> только когда пользователь закрыл экран и UI-контекст скоро будет очищен у игрока.</p>

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var button = ui.button("Push me").id("button");

        // Place a button in the middle of the screen
        button.rxy(0.5, 0.5).wh(80, 20).anchor(0.5);
        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();

        // Check if the user closed the screen
        if (uiContext.isClosed())
        {
            // Do something with the data
            c.getSubject().send("Welcome back to the world!");
        }
    }
 }</pre>

Возвращает ID последнего отредактированного компонента UI.

 <p>Если изменено несколько элементов UI (см. {@link UIComponent#updateDelay(int)}), вернётся только последний.</p>

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var title = ui.label("...").id("title");
        var name = ui.textbox().id("name");
        var lastname = ui.textbox().id("lastname");

        // Place two text fields in the middle of the screen
        name.rxy(0.5, 0.5).wh(140, 20).anchor(0.5);
        lastname.rx(0.5).ry(0.5, 25).wh(140, 20).anchor(0.5);
        title.rx(0.5).y(20).wh(140, 20).anchorX(0.5);
        title.labelAnchor(0.5, 0.5);

        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();
        var last = uiContext.getLast();

        // Depending on the last value, update the title accordingly
        if (last === "name")
        {
            uiContext.get("title").label("Name: " + uiContext.getData().getString("name"));
        }
        else if (last === "lastname")
        {
            uiContext.get("title").label("Last name: " + uiContext.getData().getString("lastname"));
        }
    }
 }</pre>

Возвращает компонент UI по заданному ID или <code>null</code>. Используйте это в обработчике UI, чтобы менять свойства конкретного компонента.

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var button = ui.button("Push me").id("button");

        // Place a button in the middle of the screen
        button.rxy(0.5, 0.5).wh(80, 20).anchor(0.5);
        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();

        if (uiContext.getLast() === "button")
        {
            uiContext.get("button").label("Push me harder!");
        }
    }
 }</pre>

Отправляет изменения UI игроку.

 <p>Если вы меняли данные компонентов UI-контекста через {@link IMappetUIContext#get(String)} вне обработчика (контекст после выполнения обработчика сам отправляет изменения), вызовите эту функцию вручную, чтобы отправить обновления игроку.</p>

 <pre>{@code
    // ui.js
    function main(c)
    {
        var ui = mappet.createUI().background();
        var button = ui.button("Push me").id("button");

        // Place a button in the middle of the screen
        button.rxy(0.5, 0.5).wh(80, 20).anchor(0.5);
        c.getSubject().openUI(ui);
    }

    // other.js
    function main(c)
    {
        var uiContext = c.getSubject().getUIContext();

        // Assuming that UI context is still present (i.e. the UI is still open)
        if (uiContext)
        {
            uiContext.get("button").label("Too late!");
            uiContext.sendToPlayer();
        }
    }
 }</pre>

