Интерфейс для работы с квестами игрока Mappet.

 <pre>{@code
    function main(c)
    {
        // Assuming that subject entity is a IScriptPlayer
        var quests = c.getSubject().getQuests();

        // Do something with quests...
    }
 }</pre>

methods.doc:
Проверяет, есть ли в наборе квест с указанным ID.

 <pre>{@code
    if (c.getSubject().getQuests().has("important_quest"))
    {
        // § is section symbol
        c.getSubject().send("You can't do this until you finish §6Important quest§r!");
    }
 }</pre>

Добавляет квест в набор квестов по указанному ID.

 <pre>{@code
    if (c.getSubject().getQuests().add("important_quest"))
    {
        c.getSubject().send("Check your quests!");
    }
    else
    {
        c.getSubject().send("You already have this quest, huh...");
    }
 }</pre>

Проверяет, можно ли завершить квест с указанным ID.

 <pre>{@code
    if (c.getSubject().getQuests().isComplete("important_quest"))
    {
        c.getSubject().send("I think you should bring this quest back to Steve!");
    }
 }</pre>

Завершает квест из набора по указанному ID и выдаёт награду.

 <pre>{@code
    if (c.getSubject().getQuests().complete("important_quest"))
    {
        c.getSubject().send("Important quest was successfully completed!");
    }
    else
    {
        c.getSubject().send("Finish your objectives first...");
    }
 }</pre>

Удаляет квест из набора по указанному ID.

 <pre>{@code
    if (c.getSubject().getQuests().decline("important_quest"))
    {
        c.getSubject().send("You failed the objective... you'll need to retake quest  !");
    }
 }</pre>

Возвращает все ID квестов в наборе.

 <pre>{@code
    var quests = c.getSubject().getQuests();
    var ids = quests.getIds();
    var completedAll = true;

    for each (var id in ids)
    {
        if (!quests.isComplete(id))
        {
            completedAll = false;

            break;
        }
    }

    if (completedAll)
    {
        c.getSubject().send("You need to complete all before you can do this...");
    }
 }</pre>

Преобразует NBT-список в Java-массив.\n\n <pre>{@code
     var tag = mappet.createCompound("{id:[0,2,4]}");

     c.send(tag.get("id").toArray()[1]); // 2
 }</pre>

Установить произвольный NBT.

 <pre>{@code
    var compound = mappet.createCompound();

    compound.setNBT("stack", '{id:"minecraft:diamond",Count:64b}');

    // {stack:{id:"minecraft:diamond",Count:64b}}
    print(compound.stringify());
 }</pre>

Получить значение по ключу в исходном типе. Возможные типы: INBTCompound, INBTList, String, Double, Long, Float, Int, Short, Byte или null, если ключ отсутствует.

 <pre>{@code
     var tag = mappet.createCompound("{id:\"minecraft:diamond_hoe\",Count:1b}");

     c.send(tag.get("id"));
     c.send(tag.get("Count"));
 }</pre>

Сравнивает этот компаунд с другим — порядок ключей не важен.

 <pre>{@code
     var tag1 = mappet.createCompound("{id:\"minecraft:diamond_hoe\",Count:1b}");
     var tag2 = mappet.createCompound("{Count:1b,id:\"minecraft:diamond_hoe\"}");

     c.send(tag1.equals(tag2));
 }</pre>

Добавляет вложенный компаунд в этот компаунд.

 <pre>{@code
    var tag = mappet.createCompound();
    tag.addCompound("compound");
    tag.get("compound").setString("x", "123")
    c.send(tag) //{compound:{x:"123"}}
 }</pre>

Выгружает в JSON-строку. Сначала приводит к корректному JSON-формату ключ:значение. Затем ищет числовые литералы и булевы значения, проверяет совпадения "0b" и "1b" и заменяет их на false и true; в остальных случаях удаляет последний символ совпадения, убирая суффикс типа.

 <pre>{@code
   var tag = mappet.createCompound("{id:\"minecraft:diamond_hoe\",Count:1b}");
   c.send(tag.dumpJSON());
 }</pre>

classes.doc:
Компонент пользовательского интерфейса Trackpad.

<p>Компонент позволяет вводить числа (целые и дробные) с необязательным ограничением диапазона между min и max. Пользователь может менять значение стрелками сбоку или вводить его вручную.</p>

<p>Если задан ID, в данные контекста UI записывается число, показанное в поле: при включённой опции integer сохраняется целое число, иначе — дробное.</p>

<p>Этот компонент можно создать с помощью метода {@link IMappetUIBuilder#trackpad()}.</p>

<pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var trackpad = ui.trackpad(5).id("number").limit(0, 25, true);

        trackpad.rxy(0.5, 0.5).wh(160, 20).anchor(0.5);
        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();
        var data = uiContext.getData();

        if (uiContext.getLast() === "number")
        {
            // If integer wasn't enabled, you would use:
            // data.getDouble("number")
            if (data.getInt("number") === 19)
            {
                c.getSubject().send("21");
            }
        }
    }
 }</pre>

Компонент переключателя.

 <p>Компонент задаёт булево значение (yes/no, true/false, <code>1</code>/<code>0</code>). Если указан ID, в данные UI-контекста записывается значение типа boolean.</p>

 <p>Создаётся методом {@link IMappetUIBuilder#toggle(String)}.</p>

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, \"handler\").background();
        var trackpad = ui.toggle(\"Show\", false).id(\"toggle\");
        var label = ui.label(\"You can see this label\").id(\"label\");

        trackpad.rxy(0.5, 0.5).wh(160, 20).anchor(0.5);
        label.rx(0.5).ry(0.5, 25).wh(160, 20).anchor(0.5).labelAnchor(0.5);
        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();
        var data = uiContext.getData();

        if (uiContext.getLast() === \"toggle\")
        {
            uiContext.get(\"label\").visible(uiContext.getData().getBoolean(\"toggle\"));
        }
    }
 }</pre>

methods.doc:
Устанавливает состояние переключателя.

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext
    uiContext.get(\"toggle\").state(true);
 }</pre>

classes.doc:
Текстовый компонент.

 <p>Компонент для большого объёма текста. Поддерживает несколько строк и форматирование Minecraft: вместо символа секции используйте "[". Компонент меняет размер внутри элементов column и row, поэтому отлично подходит для макетов.</p>

 <p>Этот компонент можно создать с помощью метода {@link IMappetUIBuilder#text(String)}.</p>

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI().background();
        var scroll = ui.column(5, 10);

        scroll.getCurrent().scroll().rxy(0.5, 0.5).w(200).rh(0.8).anchor(0.5);

        var text = scroll.text("Lorem ipsum dolor sit amet,\n\n" +
            "consectetur adipiscing elit. Nullam sit amet luctus tellus. Sed posuere, orci quis vehicula mattis, orci nulla malesuada nunc, in mattis mi urna a quam. Mauris malesuada tempus molestie. Pellentesque in est quam. Sed iaculis dictum bibendum. Cras eleifend varius ligula, id luctus arcu ultricies a. Nam tincidunt mauris eu ligula sodales faucibus sed ut eros. Phasellus consectetur nec magna quis fermentum. Donec quis mauris tristique neque suscipit placerat. Etiam id laoreet ante. Maecenas finibus nec augue vitae convallis.\n\n" +
            "Donec at tortor nibh. Nunc quis nulla justo. Vestibulum lacinia quis sapien at euismod. Curabitur sed maximus sapien. Fusce sed dui at lectus venenatis volutpat ac ac sapien. Cras at tortor pellentesque, finibus nulla vitae, tristique ligula. Etiam porta elementum justo. Cras facilisis rutrum mauris ac consectetur. Aliquam ipsum dolor, accumsan et lacus malesuada, volutpat pretium odio. Donec sed purus vulputate, auctor nulla in, sagittis ipsum. Nam dolor tortor, consequat sit amet eleifend at, imperdiet at ligula. Aenean blandit sem sit amet ex vehicula consequat. Etiam feugiat condimentum sem, eget imperdiet augue mattis quis.");

        c.getSubject().openUI(ui);
    }
 }</pre>

methods.doc:
Устанавливает горизонтальную точку привязки текста — где внутри рамки будет отрисован текст.

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext

    // Position the text's content in the center of its frame
    uiContext.get("text").textAnchor(0.5);
 }</pre>

classes.doc:
Текстовое поле (одна строка).

 <p>Компонент для ввода одной строки текста — если нужен многострочный ввод, используйте {@link UITextareaComponent}. Например, можно попросить игрока ввести имя.</p>

 <p>Если у компонента задан ID, введённая строка сохраняется в данных UI-контекста под этим ID.</p>

 <p>Этот компонент можно создать с помощью метода {@link IMappetUIBuilder#textbox()}.</p>

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var textbox = ui.textbox().id("textbox").tooltip("Enter your name:");

        textbox.rxy(0.5, 0.5).wh(160, 20).anchor(0.5);
        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();
        var data = uiContext.getData();

        if (uiContext.getLast() === "textbox")
        {
            c.getSubject().send("Your name is: " + data.getString("textbox"));
        }
    }
 }</pre>

methods.doc:
Устанавливает максимальную длину текста (максимум вводимых символов).

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext
    uiContext.get("textbox").maxLength(68);
 }</pre>

Отключает фон текстового поля.

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext
    uiContext.get("textbox").noBackground();
 }</pre>

classes.doc:
Компонент UI — многострочное текстовое поле.

 <p>Позволяет вводить несколько строк (для однострочного используйте компонент {@link UITextboxComponent}). Подходит, например, для многострочного описания игрока.</p>

 <p>Если компоненту указан ID, в данные UI-контекста запишется введённая пользователем многострочная строка.</p>

 <p>Создаётся вызовом {@link IMappetUIBuilder#textarea(String)}.</p>

 <pre>{@code
    function main(c)
    {
        var s = c.getSubject();
        var story = s.getStates().getString("story");
        var ui = mappet.createUI(c, "handler").background();
        var textarea = ui.textarea(story).id("textarea").tooltip("Tell us your story...");

        // Don't send updates too often, only half a second after the player
        // stopped typing into a text area
        textarea.updateDelay(500);
        textarea.rxy(0.5, 0.5).wh(300, 200).anchor(0.5);
        s.openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();
        var data = uiContext.getData();

        if (uiContext.getLast() === "textarea")
        {
            // Write down the input
            c.getSubject().getStates().setString("story", data.getString("textarea"));
        }
    }
 }</pre>

methods.doc:
Отключить фон текстовой области.

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext
    uiContext.get("textarea").noBackground();
 }</pre>

classes.doc:
Компонент UI — список строк.

 <p>Показывает список строк, из которого игрок выбирает один элемент.</p>

 <p>Если у компонента есть ID, выбранная строка записывается в данные UI-контекста.</p>

 <p>Создаётся через {@link IMappetUIBuilder#stringList(List)}.</p>

 <pre>{@code
    function main(c)
    {
        var s = c.getSubject();
        var ui = mappet.createUI(c, "handler").background();
        var strings = ui.stringList(["Apple", "Orange", "Pineapple", "Avocado"]).id("strings").tooltip("Pick a fruit...");
        var label = ui.label("...").id("fruit").visible(false);

        strings.background(0x88000000).rxy(0.5, 0.5).wh(100, 240).anchor(0.5);
        label.rx(0.5).ry(0.5, -160).anchor(0.5, 0.5);
        label.background(0x88000000).labelAnchor(0.5, 0.5);
        s.openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();
        var data = uiContext.getData();

        if (uiContext.getLast() === "strings")
        {
