Графический UI-компонент.

<p>Компонент рисует одноцветные и градиентные прямоугольники, изображения (через менеджер текстур Minecraft), текст и иконки McLib — простейший canvas.</p>

<p>Создаётся через {@link IMappetUIBuilder#graphics()}.</p>

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();

        // Background rendering
        var back = ui.graphics().rx(0.5, -150).ry(1, -250).wh(300, 250);
        var icons = Java.type("mchorse.mclib.client.gui.utils.IconRegistry").icons.keySet();

        back.shadow(80, 80, 300 - 160, 250 - 160, 0x88ff1493, 0x00ff1493, 80);
        back.shadow(80, 80, 300 - 160, 250 - 160, 0x880088ff, 0x000088ff, 40);

        for each (var icon in icons)
        {
            var x = Math.random() * 280 + 10;
            var y = Math.random() * 230 + 10;

            back.icon(icon, x - 1, y - 1, 0xff000000 + Math.random() * 0xffffff);
        }

        // Draw my favorite "me"
        var m = mappet.createMorph("{Skin:\"blockbuster:textures/entity/mchorse/skin.png\",CustomPose:{Size:[0.6f,1.8f,0.6f],Poses:{right_arm:{P:[-6.0f,-2.0f,0.0f],R:[-90.0f,-31.0f,0.0f]},left_leg:{P:[2.0f,-12.0f,0.0f]},right_armwear:{P:[0.0f,-4.0f,0.0f]},outer:{P:[0.0f,4.0f,0.0f]},left_legwear:{P:[0.0f,-6.0f,0.0f]},body:{P:[0.0f,8.0f,0.0f],R:[0.0f,-29.0f,0.0f]},bodywear:{P:[0.0f,-6.0f,0.0f]},head:{P:[0.0f,8.0f,0.0f],R:[7.0f,-51.0f,0.0f]},left_arm:{P:[6.0f,-2.0f,0.0f]},right_leg:{P:[-2.0f,-12.0f,0.0f]},right_legwear:{P:[0.0f,-6.0f,0.0f]},anchor:{P:[0.0f,16.0f,0.0f]},left_armwear:{P:[0.0f,-4.0f,0.0f]}}},BodyParts:[{Limb:\"head\",Morph:{Settings:{Hands:1b},Name:\"blockbuster.mchorse/head\"}}],Settings:{Hands:1b},Name:\"blockbuster.fred_3d\"}");
        var morph = ui.morph(m).id("icon");

        morph.rx(0.5, -150).ry(1, -250).wh(300, 250).position(-0.017, 1.367, 0).rotation(0, 0).distance(2.2).fov(40).enabled(false);

        // Draw foreground
        var graphics = ui.graphics().rx(0.5, -150).ry(1, -250).wh(300, 250);

        // Draw small rectangles
        for (var i = 0; i < 100; i++)
        {
            var x = Math.random() * 280 + 10;
            var y = Math.random() * 230 + 10;

            graphics.rect(x - 1, y - 1, 2, 2, 0x88000000 + Math.random() * 0xffffff);
        }

        graphics.gradient(0, 210, 300, 40, 0x00ff0000, 0xffff0000);
        // This is Thanos' infinity gauntlet. just sayin in case it gets removed xd
        graphics.image("https://i.pinimg.com/originals/6d/5a/99/6d5a99fa0f01dff1dd5de5e3b8244f8d.png", 0, 75, 55, 100);
        graphics.text("McThanos", 120, 230, 0xffffff);

        ui.label("Graphic Design is my passion").color(0x00ff00).background(0x88000000).rxy(0.5, 0.25).wh(100, 20).anchor(0.5).labelAnchor(0.5);

        c.getSubject().openUI(ui);
    }
 }</pre>

methods.doc:
Устанавливает подсказку, которая отображается с указанной стороны рамки компонента.

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext
    uiContext.get("component").tooltip("Enter your full name", 1);
 }</pre>

Устанавливает видимость компонента. Скрытый компонент не принимает ввод — даже если кнопка невидима, по ней нельзя кликнуть.

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext
    uiContext.get("button").visible(false);
 }</pre>

Включает или отключает ввод для компонента. Отключённый компонент не принимает ввод: нельзя вводить текст или фокусировать textbox/textarea, нельзя нажимать на click area, icon button или button и т.д.

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext
    uiContext.get("button").enabled(false);
 }</pre>

Устанавливает отступ со всех сторон.

 <p><b>ВАЖНО</b>: отступы влияют на позиционирование только внутри layout-компонента. Они не работают за пределами column, row и grid layout-компонентов.</p>

 <pre>{@code
    // Assuming that uiContext is a IMappetUIContext
    uiContext.get("button").margin(10);
 }</pre>

Добавляет привязку клавиши с модификаторами Control, Shift и Alt (при удержании).

 <pre>{@code
    // For more reference, check this page to find the list of all key codes:
    // https://minecraft.fandom.com/wiki/Key_codes/Keyboard1
    //
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var button = ui.icon("upload").id("icon");

        // 203 = Arrow left
        ui.getCurrent().keybind(203, "left", "Change icon to left");
        // 205 = Arrow right
        ui.getCurrent().keybind(205, "right", "Change icon to right");
        button.rxy(0.5, 0.5).wh(20, 20).anchor(0.5);
        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();
        var key = uiContext.getHotkey();

        if (key === "left")
        {
            uiContext.get("icon").icon("leftload");
        }
        else if (key === "right")
        {
            uiContext.get("icon").icon("rightload");
        }
    }
 }</pre>

Добавляет пункт в контекстное меню.

 <pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var label = ui.label("Hello!").id("label").tooltip("Right click me...");

        label.rxy(0.5, 0.5).wh(160, 20).anchor(0.5).labelAnchor(0.5);
        label.context("bubble", "a", "How are you?");
        label.context("remove", "b", "...", 0xff0033);

        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var uiContext = c.getSubject().getUIContext();
        var data = uiContext.getData();

        if (uiContext.getLast() === "textbox")
        {
            c.getSubject().send("Your name is: " + data.getString("textbox"));
        }

        var item = uiContext.getContext();

        if (item === "a")
        {
            uiContext.get("label").label("I'm fine, and you?");
        }
        else if (item === "b")
        {
            uiContext.get("label").label("");
        }
    }
 }</pre>

Установить задержку обновления в миллисекундах (<code>1000</code> = <code>1</code> секунда).

 <p>Задержка ограничивает частоту отправки данных с клиента в скрипт-обработчик.</p>

 <pre>{@code
    // Assuming that ui is a IMappetUIBuilder

    // Change text box's update delay to 1 second meaning
    // that a second after user didn't type anything into
    // the text box it will send all the data to the handler script
    ui.textbox().id(\"name\").updateDelay(1000);
 }</pre>

Плавно изменяет масштаб компоненты. По умолчанию используется мягкая встроенная кривая <code>sine_inout</code>. Длительность указывается в тиках: 20 тиков равны одной секунде.

 <pre>{@code
    // Увеличить компоненту с лёгким пружинящим эффектом
    uiContext.get(\"button\").scaleTo(1.5, 10, \"elastic_out\");
 }</pre>

Плавно изменяет цвет фона компоненты через выбранную встроенную кривую. По умолчанию используется мягкая встроенная кривая <code>sine_inout</code>.

 <pre>{@code
    uiContext.get(\"button\").colorTo(0x00aaff, 20, \"sine_inout\");
 }</pre>

Плавно перемещает компоненту в относительные координаты <code>rxy</code>. Значения <code>x</code> и <code>y</code> — от 0 до 1 и учитывают текущий <code>anchor</code> компоненты. По умолчанию используется встроенная кривая <code>sine_inout</code>.

 <pre>{@code
    // То же положение, что rxy(0.8, 0.3)
    uiContext.get("button").moveTo(0.8, 0.3, 15, "back_out");
 }</pre>

Плавно поворачивает компоненту вокруг её центра по выбранной встроенной кривой. По умолчанию используется <code>sine_inout</code>.

 <pre>{@code
    uiContext.get("button").rotateTo(360, 20, "quad_inout");
 }</pre>

classes.doc:
Компонент области клика.

<p>Невидимый компонент, который действует как поле клика. Если у компонента есть ID и игрок кликает внутри его границ, он отправляет NBT-список из 5 чисел с плавающей точкой:</p>

<ul>
    <li>Index <code>0</code> = X-координата относительно рамки области клика.</li>
    <li>Index <code>1</code> = Y-координата относительно рамки области клика.</li>
    <li>Index <code>2</code> = X-фактор (0..1) — насколько вправо по ширине области клика (<code>0</code> — левый край, <code>1</code> — правый край).</li>
    <li>Index <code>3</code> = Y-фактор (0..1) — насколько вниз по высоте области клика (<code>0</code> — верхний край, <code>1</code> — нижний край).</li>
    <li>Index <code>4</code> = Кнопка мыши (<code>0</code> — левая, <code>1</code> — правая, <code>2</code> — средняя и т.д.).</li>
</ul>

<p>Создаётся вызовом {@link IMappetUIBuilder#click()}.</p>

<pre>{@code
   function main(c)
   {
       var ui = mappet.createUI(c, "handler").background();
       var click = ui.click().id("click");
       var backdrop = ui.graphics().id("backdrop");

       backdrop.rxy(0.5, 0.5).wh(300, 150).anchor(0.5);
       backdrop.rect(0, 0, 300, 150, 0x88000000);
       click.rxy(0.5, 0.5).wh(300, 150).anchor(0.5);
       c.getSubject().openUI(ui);
   }

   function handler(c)
   {
       var uiContext = c.getSubject().getUIContext();
       var data = uiContext.getData();

       if (uiContext.getLast() === "click")
       {
           // Math.floor just in case there are precision issues
           var list = data.getList("click");
           var x = Math.floor(list.getFloat(0));
           var y = Math.floor(list.getFloat(1));
           var fx = list.getFloat(2);
           var fy = list.getFloat(3);
           var button = Math.floor(list.getFloat(4));

           // Draw random rectangle on the back drop
           if (button === 0)
           {
               var backdrop = uiContext.get("backdrop");

               backdrop.rect(x - 10, y - 10, 20, 20, 0xff000000 + Math.floor(Math.random() * 0xffffff));
           }
       }
   }
 }</pre>

Кликабельный компонент кнопки.

<p>Плоский цветной прямоугольник с подписью, который при нажатии вызывает обработчик. Если у кнопки есть ID, в данных UI-контекста под этим ID хранится число нажатий.</p>

<p>Создаётся вызовом {@link IMappetUIBuilder#button(String)}.</p>

<pre>{@code
   function main(c)
   {
       var ui = mappet.createUI(c, "handler").background();
       var button = ui.button("Start...").id("button");

       button.rxy(0.5, 0.5).wh(160, 20).anchor(0.5);
       c.getSubject().openUI(ui);
   }

   function handler(c)
   {
       var uiContext = c.getSubject().getUIContext();

       if (uiContext.getLast() === "button")
       {
           var data = uiContext.getData();
           var pressed = data.getInt("button");

           if (pressed >= 100)
           {
               c.send("We have a winner!");
           }

           uiContext.get("button").label("You pressed: " + pressed);
       }
   }
 }</pre>

methods.doc:
Изменить цвет фона кнопки, указав шестнадцатеричный RGB.

<pre>{@code
   // Assuming that uiContext is a IMappetUIContext
   uiContext.get("button").background(0x00ff00);
 }</pre>

Отключить фон кнопки.

<pre>{@code
   // Assuming that uiContext is a IMappetUIContext
   uiContext.get("button").noBackground();
 }</pre>

Включает событие наведения для этой кнопки. Когда игрок впервые наведёт курсор на кнопку, Mappet вызовет обработчик. В обработчике используй <code>c.getSubject().getUIContext().getHovered()</code>, чтобы получить ID наведённой кнопки. Событие срабатывает один раз при входе курсора, а не каждый кадр.

<pre>{@code
function main(c) {
    let ui = mappet.createUI(c, "handler").background();
    ui.button("Показать подсказку").id("help").enterHover().exitHover().rxy(0.5, 0.6).wh(160, 20).anchor(0.5);
    ui.label("").id("hint").rxy(0.5, 0.5).wh(160, 20).anchor(0.5).labelAnchor(0.5);

    c.getSubject().openUI(ui);
}

function handler(c) {
    let ui = c.getSubject().getUIContext();

    if (ui.getHovered() === "help") {
        ui.get("hint").label("На эту кнопку навели курсор.");
    }

    if (ui.getUnhovered() === "help") {
        ui.get("hint").label("");
    }
}
}</pre>

Включает событие ухода курсора с этой кнопки. Его можно отменить. Когда игрок уводит курсор с кнопки, Mappet один раз вызывает обработчик UI. ID кнопки доступен через <code>c.getSubject().getUIContext().getUnhovered()</code>. Можно включить оба события в одну цепочку: <code>button.enterHover().exitHover()</code>.

<pre>{@code
// Очистить подсказку, когда курсор ушёл с кнопки
if (ui.getUnhovered() === "help") {
    ui.get("hint").label("");
}
}</pre>

Переназначить привязку клавиши у выбранного игрока в Minecraft. <code>id</code> — ID привязки клавиши. Можно передать строку прямо из <code>options.txt</code>, например <code>key_key.jump</code>, <code>key_key.forward</code> или <code>key_key.attack</code>; также поддерживается вариант без первого <code>key_</code>, например <code>key.jump</code>. <code>key</code> — имя клавиши из <code>options.txt</code>, например <code>key.keyboard.space</code>, <code>key.keyboard.f</code> или <code>key.mouse.left</code>. Новое назначение применяется сразу в Minecraft и сразу записывается в <code>options.txt</code>. Передайте <code>key.keyboard.unknown</code>, чтобы снять назначение.

<pre>{@code
var settings = c.getSubject().getSettings();

// Прыжок на F
settings.setKeyBinding("key_key.jump", "key.keyboard.f");

// Инвентарь на R
settings.setKeyBinding("key_key.inventory", "key.keyboard.r");

// Атаку на левую кнопку мыши
settings.setKeyBinding("key_key.attack", "key.mouse.left");
}</pre>

Сбросить привязку клавиши к её стандартному значению в Minecraft.

<pre>{@code
c.getSubject().getSettings().resetKeyBinding("key.jump");
}</pre>

Запускает action-анимацию у Chameleon-морфа, установленного на выбранной руке. Если на руке нет Chameleon-морфа или action с таким именем отсутствует, метод ничего не делает. <pre>{@code
function main(c)
{
    c.subject.getHand(0).playAnimation("attack");
}
}</pre>

Включает или выключает отрисовку элемента. <pre>{@code
function main(c)
{
    c.getSubject().getAllHud("Название").hotbar.render(false);
}
}</pre>

Сдвигает элемент относительно ванильной позиции в пикселях. Положительное X — вправо, положительное Y — вниз. <pre>{@code
function main(c)
{
    c.getSubject().getAllHud("Название").crosshair.pos(20, -10);
}
}</pre>

Разрешить этому виртуальному фонарику использовать не только воздух, но и координаты не-твёрдых не-жидких блоков. Этот метод не создаёт <code>minecraft:light</code>, не сохраняет и не восстанавливает BlockState — существующие блоки остаются на месте. Твёрдые блоки, вода и лава не используются.

<pre>{@code
var ray = c.getSubject().rayTrace(24);
ray.displayFlashlight("flashlight", 2, 1, 15, 0.5).nonSolidIgnore();
}</pre>

packages.doc:
Раздел про основной Scripting API.

<p>Ниже — пример скрипта. Поместите этот код в папку мира
<code>mappet/scripts/example.js</code> и выполните команду
<code>/mp script eval @r example</code> — вас телепортирует в
(249, 56, -789) и в чате появится сообщение.</p>

<pre>{@code
    function main(c)
    {
        // Teleport the subject entity to specific coordinates, and
        // send a message to everyone on the server
        c.getSubject().setPosition(249, 56, -789);

        c.send("Teleported " + c.getSubject().getName() + " to (249, 56, -789)");
    }
 }</pre>

UI API — это API для создания графических пользовательских интерфейсов (UI). Его можно использовать для множества задач:

<p>Система диалогов, блокировка ввода пользователя, дневники (поиск заметок, журналов, фрагментов лора и т.д.), мини‑игры, открывание дверей, игры «укажи и кликни», экран создания персонажа, админ‑инструменты, предложения пользовательских заданий и т.д.</p>

<p><b>Все</b> компоненты UI основаны на {@link mchorse.mappet.api.ui.components.UIComponent}, поэтому у них есть методы UIComponent.</p>

<p>Ниже — простой пример: при нажатии на кнопку предмет выпадет в мир.</p>

<pre>{@code
    function main(c)
    {
        var ui = mappet.createUI(c, "handler").background();
        var button = ui.button("Give me a diamond!").id("button");

        button.rxy(0.5, 0.5).wh(160, 20).anchor(0.5);
        c.getSubject().openUI(ui);
    }

    function handler(c)
    {
        var s = c.getSubject();
        var uiContext = s.getUIContext();

        if (uiContext.getLast() === "button")
        {
            var pos = s.getPosition();

            c.getWorld().dropItemStack(mappet.createItem("minecraft:diamond"), pos.x, pos.y + 2, pos.z);
        }
    }
 }</pre>
